/**
 * @name Path traversal vulnerability in file operations
 * @description Detects path traversal vulnerabilities where user input can control file paths
 * @kind path-problem
 * @problem.severity high
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // File open operations
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // os.path operations that could lead to file access
      call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "realpath"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // Direct file system access
      call = API::moduleImport("os").getMember(["open", "chdir", "remove", "unlink", "rename"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source, "user input"

/**
 * @name Path traversal in file operations
 * @description Reading files with untrusted path input can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        // File open operations
        call = API::moduleImport("builtins").getMember("open").getACall() or
        call = API::moduleImport("os").getMember(["open", "fdopen"]).getACall() or
        call = API::moduleImport("io").getMember(["open", "FileIO"]).getACall() or
        // Path operations
        call = API::moduleImport("os.path").getMember(["join", "abspath", "realpath"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source, "user input"
